import React from 'react';
import type { SpecialistDetails } from '../../types/claim';
import { SpecialistCard, type SpecialistCardItem } from './SpecialistCard';

const inputClass =
  'w-full rounded-lg border border-[#d2d3d6] bg-white px-3 py-2 text-[16px] leading-[28px] text-[#4d4f5c] placeholder:text-[#949494] focus:outline-none focus:border-[#0055b7]';
const labelClass = 'block text-[14px] leading-[24px] font-medium text-[#4d4f5c] mb-1';

/** Mock Doctify-style specialists (physical) */
export const SPECIALIST_CARDS: SpecialistCardItem[] = [
  { id: '1', name: 'Dr Sarah Mitchell', specialty: 'Orthopaedic Surgeon', gpHospital: 'London Bridge Hospital' },
  { id: '2', name: 'Dr James Chen', specialty: 'Sports Medicine', gpHospital: 'The Wellington Hospital' },
  { id: '3', name: 'Dr Emma Watson', specialty: 'Rheumatology', gpHospital: 'Harley Street Clinic' },
  { id: '4', name: 'Dr David Okonkwo', specialty: 'Neurology', gpHospital: 'The Lister Hospital' },
];

/** Mock Doctify-style mental health specialists */
export const MENTAL_SPECIALIST_CARDS: SpecialistCardItem[] = [
  { id: 'm1', name: 'Dr Rachel Green', specialty: 'Clinical Psychologist', gpHospital: 'Priory Wellbeing Centre' },
  { id: 'm2', name: 'Dr Tom Hughes', specialty: 'Psychiatrist', gpHospital: 'Nightingale Hospital' },
  { id: 'm3', name: 'Dr Anna Kowalski', specialty: 'CBT Therapist', gpHospital: 'Therapy Centre London' },
  { id: 'm4', name: 'Dr Luke Williams', specialty: 'Counselling Psychologist', gpHospital: 'Harley Therapy' },
];

type MiniFormSpecialistProps = {
  question: number;
  type: 'specialist' | 'mental specialist';
  value: SpecialistDetails | null;
  onChange: (updates: Partial<SpecialistDetails>) => void;
  className?: string;
};

/** question=11, type=specialist or type=mental specialist – Name of Specialist + Doctify cards */
export const MiniFormSpecialist: React.FC<MiniFormSpecialistProps> = ({
  question,
  type,
  value,
  onChange,
  className = '',
}) => {
  const name = value?.name ?? '';
  const cards = type === 'mental specialist' ? MENTAL_SPECIALIST_CARDS : SPECIALIST_CARDS;

  return (
    <div
      className={`rounded-lg border border-[#d2d3d6] bg-white p-4 space-y-4 ${className}`}
      data-variant={`question-${question}-${type}`}
    >
      <div>
        <label className={labelClass}>Name of specialist</label>
        <input
          type="text"
          value={name}
          onChange={(e) => onChange({ name: e.target.value })}
          placeholder="Select a specialist below or type name"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Or choose from specialists</label>
        <div className="grid gap-3 sm:grid-cols-2">
          {cards.map((card) => (
            <SpecialistCard
              key={card.id}
              specialist={card}
              selected={name === card.name}
              onSelect={() => onChange({ name: card.name, gpHospital: card.gpHospital, specialties: card.specialty ? [card.specialty] : undefined })}
            />
          ))}
        </div>
      </div>
    </div>
  );
};

export default MiniFormSpecialist;
