import React from 'react';
import type { SolicitorDetails } from '../../types/claim';

const inputClass =
  'w-full rounded-lg border border-[#d2d3d6] bg-white px-3 py-2 text-[16px] leading-[28px] text-[#4d4f5c] placeholder:text-[#949494] focus:outline-none focus:border-[#0055b7]';
const labelClass = 'block text-[14px] leading-[24px] font-medium text-[#4d4f5c] mb-1';

type MiniFormSolicitorProps = {
  value: SolicitorDetails | null;
  onChange: (updates: Partial<SolicitorDetails>) => void;
  className?: string;
};

/** question=8, type=legal responsibility – solicitor details */
export const MiniFormSolicitor: React.FC<MiniFormSolicitorProps> = ({
  value,
  onChange,
  className = '',
}) => {
  const d = value ?? {
    dateOfIncident: null,
    solicitorName: '',
    caseHandler: '',
    solicitorAddress: '',
    solicitorPhone: '',
    solicitorEmail: '',
    caseReference: '',
  };

  return (
    <div
      className={`rounded-lg border border-[#d2d3d6] bg-white p-4 space-y-4 ${className}`}
      data-variant="question-8-legal-responsibility"
    >
      <div>
        <label className={labelClass}>Date of incident</label>
        <input
          type="date"
          value={d.dateOfIncident ?? ''}
          onChange={(e) => onChange({ dateOfIncident: e.target.value || null })}
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Solicitor name</label>
        <input
          type="text"
          value={d.solicitorName}
          onChange={(e) => onChange({ solicitorName: e.target.value })}
          placeholder="Name of solicitor or firm"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Case handler</label>
        <input
          type="text"
          value={d.caseHandler}
          onChange={(e) => onChange({ caseHandler: e.target.value })}
          placeholder="If applicable"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Solicitor address</label>
        <input
          type="text"
          value={d.solicitorAddress}
          onChange={(e) => onChange({ solicitorAddress: e.target.value })}
          placeholder="Address"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Phone</label>
        <input
          type="tel"
          value={d.solicitorPhone}
          onChange={(e) => onChange({ solicitorPhone: e.target.value })}
          placeholder="Phone number"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Email</label>
        <input
          type="email"
          value={d.solicitorEmail}
          onChange={(e) => onChange({ solicitorEmail: e.target.value })}
          placeholder="Email"
          className={inputClass}
        />
      </div>
      <div>
        <label className={labelClass}>Case reference</label>
        <input
          type="text"
          value={d.caseReference}
          onChange={(e) => onChange({ caseReference: e.target.value })}
          placeholder="If applicable"
          className={inputClass}
        />
      </div>
    </div>
  );
};

export default MiniFormSolicitor;
