import React from 'react';
import QuestionLayout from '../ui/QuestionLayout';
import OptionChipGroup from '../ui/OptionChipGroup';
import MiniFormSpecialist from '../ui/MiniFormSpecialist';
import { useClaim } from '../../context/ClaimContext';
import type { ReferralServiceType } from '../../types/claim';

const REFERRAL_OPTIONS: { label: string; value: ReferralServiceType }[] = [
  { label: 'Specialist', value: 'specialist' },
  { label: 'Mental health specialist', value: 'mental_health_specialist' },
  { label: 'Therapist', value: 'therapist' },
  { label: 'Mental health therapist', value: 'mental_health_therapist' },
  { label: 'Direct test', value: 'direct_test' },
];

export const Step11ServiceReferral: React.FC = () => {
  const { state, dispatch, updateSpecialistDetails } = useClaim();

  const handleSelect = (value: ReferralServiceType) => {
    dispatch({
      type: 'UPDATE_FIELD',
      field: 'referralServiceType',
      value,
    });
    if ((value === 'specialist' || value === 'mental_health_specialist') && !state.specialistDetails) {
      dispatch({
        type: 'UPDATE_SPECIALIST_DETAILS',
        updates: { name: '' },
      });
    }
  };

  const handleSpecialistChange = (updates: Partial<NonNullable<typeof state.specialistDetails>>) => {
    updateSpecialistDetails(updates);
  };

  const showSpecialistForm =
    state.referralServiceType === 'specialist' || state.referralServiceType === 'mental_health_specialist';
  const type = state.referralServiceType === 'mental_health_specialist' ? 'mental specialist' : 'specialist';

  return (
    <QuestionLayout
      partLabel="Part 4 – Referral"
      currentIndex={3}
      total={4}
      question="For which service were you referred?"
    >
      <OptionChipGroup
        options={REFERRAL_OPTIONS}
        value={state.referralServiceType}
        onChange={handleSelect}
      />

      {showSpecialistForm && (
        <div className="mt-4">
          <MiniFormSpecialist
            question={11}
            type={type}
            value={state.specialistDetails}
            onChange={handleSpecialistChange}
          />
        </div>
      )}
    </QuestionLayout>
  );
};

export default Step11ServiceReferral;
