import React from 'react';

export interface SpecialistCardItem {
  id: string;
  name: string;
  specialty?: string;
  gpHospital?: string;
}

const cardClass = (selected: boolean) =>
  `rounded-lg border p-4 text-left transition cursor-pointer ${
    selected ? 'border-[#0055b7] bg-[#cce9fb]' : 'border-[#d2d3d6] bg-white hover:border-[#0055b7]/60 hover:bg-[#f6f6f7]'
  }`;

type SpecialistCardProps = {
  specialist: SpecialistCardItem;
  selected: boolean;
  onSelect: () => void;
};

/** Doctify-style specialist card – clicking populates Name of Specialist */
export const SpecialistCard: React.FC<SpecialistCardProps> = ({
  specialist,
  selected,
  onSelect,
}) => (
  <button
    type="button"
    onClick={onSelect}
    className={cardClass(selected)}
  >
    <div className="font-medium text-[16px] leading-[28px] text-[#4d4f5c]">
      {specialist.name}
    </div>
    {specialist.specialty && (
      <div className="text-[14px] leading-[24px] text-[#949494] mt-1">
        {specialist.specialty}
      </div>
    )}
    {specialist.gpHospital && (
      <div className="text-[14px] leading-[24px] text-[#4d4f5c] mt-1">
        {specialist.gpHospital}
      </div>
    )}
  </button>
);

export default SpecialistCard;
