import React from 'react';
import QuestionLayout from '../ui/QuestionLayout';
import { useClaim } from '../../context/ClaimContext';

/** Previous hospital chips – clicking one populates the hospital/clinic input */
export const PREVIOUS_HOSPITALS = [
  'London Bridge Hospital',
  'The Wellington Hospital',
  'Harley Street Clinic',
  'The Lister Hospital',
  'Nightingale Hospital',
  'Priory Wellbeing Centre',
  'Other',
] as const;

const inputClass =
  'w-full rounded-lg border border-[#d2d3d6] bg-white px-3 py-2 text-[16px] leading-[28px] text-[#4d4f5c] placeholder:text-[#949494] focus:outline-none focus:border-[#0055b7]';
const labelClass = 'block text-[14px] leading-[24px] font-medium text-[#4d4f5c] mb-1';
const chipClass = (selected: boolean) =>
  `rounded-lg border px-4 py-2 text-[14px] leading-[24px] font-medium transition ${
    selected ? 'border-[#0055b7] bg-[#cce9fb] text-[#0055b7]' : 'border-[#d2d3d6] bg-white text-[#4d4f5c] hover:bg-[#f6f6f7]'
  }`;

export const Step12HospitalClinic: React.FC = () => {
  const { state, dispatch } = useClaim();

  const value = state.hospitalClinic ?? '';

  const handleInputChange = (v: string) => {
    dispatch({
      type: 'UPDATE_FIELD',
      field: 'hospitalClinic',
      value: v,
    });
  };

  return (
    <QuestionLayout
      partLabel="Part 4 – Referral"
      currentIndex={4}
      total={4}
      question="Which hospital or clinic will you be attending?"
    >
      <div className="space-y-4">
        <div>
          <label className={labelClass}>Hospital or clinic</label>
          <input
            type="text"
            value={value}
            onChange={(e) => handleInputChange(e.target.value)}
            placeholder="Enter hospital or clinic name"
            className={inputClass}
          />
        </div>

        <div>
          <label className={labelClass}>Previous hospital (select to auto-fill)</label>
          <div className="flex flex-wrap gap-3">
            {PREVIOUS_HOSPITALS.map((name) => (
              <button
                key={name}
                type="button"
                onClick={() => handleInputChange(name)}
                className={chipClass(value === name)}
              >
                {name}
              </button>
            ))}
          </div>
        </div>
      </div>
    </QuestionLayout>
  );
};

export default Step12HospitalClinic;
