import React, { useMemo } from 'react';
import QuestionLayout from '../ui/QuestionLayout';
import OptionChipGroup from '../ui/OptionChipGroup';
import { useClaim } from '../context/ClaimContext';

export const Step1Who: React.FC = () => {
  const { state, dispatch } = useClaim();

  const options = useMemo(
    () => [
      {
        label: 'Myself',
        value: 'self',
        relationship: 'Self',
      },
      {
        label: 'Someone else on my policy',
        value: 'other',
        relationship: 'Dependant',
      },
    ],
    []
  );

  const selectedValue = state.claimant ? (state.claimant.relationship === 'Self' ? 'self' : 'other') : null;

  const handleSelect = (value: 'self' | 'other') => {
    const option = options.find((opt) => opt.value === value);
    if (!option) return;

    dispatch({
      type: 'UPDATE_FIELD',
      field: 'claimant',
      value: {
        id: value,
        name: value === 'self' ? 'Policy holder' : 'Dependant',
        relationship: option.relationship,
      },
    });
  };

  return (
    <QuestionLayout
      partLabel="Part 1 – Claim details"
      currentIndex={1}
      total={3}
      question="Who do you want to claim for?"
    >
      <OptionChipGroup
        options={options}
        value={selectedValue}
        onChange={handleSelect}
      />
    </QuestionLayout>
  );
};

export default Step1Who;

