import React from 'react';

type SnomedResultTileProps = {
  code: string;
  name: string;
  description?: string;
  onConfirm: () => void;
  onSomethingElse: () => void;
  className?: string;
};

/**
 * SnomedResultTile
 *
 * Card for a SNOMED search result with:
 * - Code, name, optional description
 * - Primary action: "Sounds like it"
 * - Secondary action: "Something else"
 *
 * Figma variable mapping (approx):
 * - Card background: #ffffff (bg-general-primary-default)
 * - Border: #d2d3d6 (border-general-default)
 * - Radius: 8px (radius-sm → rounded-lg)
 * - Primary button: #0055b7 / hover #1276c0 (brand)
 * - Secondary button: border #d2d3d6, text #4d4f5c
 */
export const SnomedResultTile: React.FC<SnomedResultTileProps> = ({
  code,
  name,
  description,
  onConfirm,
  onSomethingElse,
  className = '',
}) => {
  return (
    <section
      className={`rounded-lg border border-[#d2d3d6] bg-white px-4 py-3 shadow-sm ${className}`}
      aria-label={`Search result ${name}`}
    >
      <div className="flex flex-col gap-1">
        <span className="text-[14px] leading-[24px] text-[#949494]">{code}</span>
        <h2 className="text-[16px] leading-[28px] font-medium text-[#4d4f5c]">{name}</h2>
        {description && (
          <p className="text-[14px] leading-[24px] text-[#4d4f5c] opacity-80">{description}</p>
        )}
      </div>

      <div className="mt-3 flex flex-wrap items-center gap-3">
        <button
          type="button"
          onClick={onConfirm}
          className="inline-flex h-11 items-center justify-center rounded-lg bg-[#0055b7] px-4 text-[16px] leading-[28px] font-medium text-white transition hover:bg-[#1276c0]"
        >
          Sounds like it
        </button>
        <button
          type="button"
          onClick={onSomethingElse}
          className="inline-flex h-11 items-center justify-center rounded-lg border border-[#d2d3d6] px-4 text-[16px] leading-[28px] font-medium text-[#4d4f5c] transition hover:bg-[#f6f6f7]"
        >
          Something else
        </button>
      </div>
    </section>
  );
};

export default SnomedResultTile;

